data.script:
const text = editor.getSelectedText();
if (!text) { context.fail('Select text to transform.'); }
else {
  const choice = SelectPrompt.create(); choice.title = 'Transform selected text';
  choice.addItem('upper', 'UPPERCASE'); choice.addItem('lower', 'lowercase');
  if (!choice.show()) { context.cancel(); }
  else { editor.setSelectedText(choice.selectedItem.id === 'upper' ? text.toUpperCase() : text.toLowerCase()); }
}
